//! `os.lazy.net.stack.v1` client: the network stack service `netd`
//! (`idl/net.midl`, docs/networking-plan.md N2).
//!
//! The stubs and the blocking [`Client`] are generated by `midlc`; this module
//! adds the domain meaning: dotted-quad addresses and the two calls that park.
//! `netd` answers a `Ping` when the echo reply arrives and a `Resolve` when the
//! resolver does, so the caller bounds them by the timeout it asked for plus a
//! little slack ([`ping`], [`resolve`]); every other call takes the IDL's bound.

use alloc::vec::Vec;

use libmessenger::client::{CallError, Deadline, Errno};
use libmessenger::{Header, Parcel, VERSION};

use super::client::Native;

/// The generated `os.lazy.net.stack.v1` stubs.
pub use messenger_generated::os_lazy_net_stack_v1 as wire;

/// Registered service name.
pub const NAME: &str = wire::SERVICE_NAME;

/// The interface id every stack parcel carries.
pub const INTERFACE: u64 = wire::INTERFACE_ID;

/// Extra time a caller waits beyond the ping's own timeout, so `netd`'s
/// timeout reply (not the caller's deadline) is what ends a lost ping.
const DEADLINE_SLACK_MS: u64 = 1_000;

/// A parcel of `method` carrying an encoded `body` (the server's reply).
pub fn parcel(method: u32, body: Vec<u8>) -> Parcel {
    Parcel {
        header: Header {
            version: VERSION,
            flags: 0,
            interface_id: INTERFACE,
            method,
            txn_id: 0,
            reply_to: 0,
            deadline_ns: 0,
        },
        body,
        ..Parcel::default()
    }
}

/// A blocking client of the stack service: `Client::connect(Native)` waits for
/// `netd` to register, `Client::try_connect(Native)` does not.
pub type Client = wire::Client<Native>;

/// The bound of a call that parks for `timeout_ms` inside `netd`.
fn parked(timeout_ms: u32) -> Deadline {
    Deadline::millis(u64::from(timeout_ms) + DEADLINE_SLACK_MS)
}

/// One echo request to `dst` and its reply; parks until one or the other.
pub fn ping(
    client: &Client,
    dst: [u8; 4],
    payload_len: u32,
    timeout_ms: u32,
) -> Result<wire::EchoResult, CallError> {
    client.ping_within(&dst, payload_len, timeout_ms, parked(timeout_ms))
}

/// Look `name` up (A records); parks until the resolver answers. `ENOENT`
/// means the resolver says the name has no address.
pub fn resolve(client: &Client, name: &str, timeout_ms: u32) -> Result<Vec<[u8; 4]>, CallError> {
    let addrs = client.resolve_within(name, timeout_ms, parked(timeout_ms))?;
    Ok(addrs
        .iter()
        .filter_map(|a| <[u8; 4]>::try_from(a.as_slice()).ok())
        .collect())
}

/// The first address of `host`: a dotted quad as it is, anything else
/// through [`resolve`].
pub fn lookup_host(client: &Client, host: &str, timeout_ms: u32) -> Result<[u8; 4], CallError> {
    if let Some(addr) = super::netstd::parse_ipv4(host) {
        return Ok(addr);
    }
    resolve(client, host, timeout_ms)?
        .first()
        .copied()
        .ok_or(CallError::Transport(Errno::NOENT))
}
